-- Phase 2: accounts and per-user isolation.
--
-- Adds the account-governance columns to "user" (role / banned / banReason /
-- banExpires, mirroring Better Auth's admin-plugin field names so adopting
-- that plugin later is a no-op) and the append-only administrator audit table.
--
-- DDL generated by `prisma migrate diff --from-schema <phase-1 schema>
-- --to-schema server/prisma/schema.prisma --script`, then the CHECK constraint
-- added by hand (Prisma's schema language cannot express it, so it is raw SQL
-- here; applied with `prisma migrate deploy` only — this repo never runs
-- `migrate dev`, which is what would report it as drift).

-- AlterTable
ALTER TABLE "user" ADD COLUMN     "banExpires" TIMESTAMP(3),
ADD COLUMN     "banReason" TEXT,
ADD COLUMN     "banned" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "role" TEXT NOT NULL DEFAULT 'user';

-- The role column is TEXT (Better Auth declares the field as a string, and the
-- auth layer validates the Prisma schema at runtime against that declaration),
-- so the two-role invariant is enforced here instead of by a Prisma enum.
ALTER TABLE "user" ADD CONSTRAINT "user_role_check" CHECK ("role" IN ('user', 'admin'));

-- CreateTable
CREATE TABLE "admin_audit_event" (
    "id" TEXT NOT NULL,
    "actorUserId" TEXT NOT NULL,
    "actorEmail" TEXT NOT NULL,
    "targetUserId" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "result" TEXT NOT NULL,
    "detail" TEXT,
    "requestId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "admin_audit_event_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "admin_audit_event_targetUserId_idx" ON "admin_audit_event"("targetUserId");

-- CreateIndex
CREATE INDEX "admin_audit_event_actorUserId_idx" ON "admin_audit_event"("actorUserId");

-- CreateIndex
CREATE INDEX "admin_audit_event_createdAt_idx" ON "admin_audit_event"("createdAt");
